// Allowlisted share encoding for the pressure-washing bid calculator. A
// shared URL must reconstruct the same job the sender priced — silently
// dropping a surface's chemical cost, the drive time, or the target margin
// is how two people compute different profits from the "same" link. Only
// these keys ride in the hash; anything else is ignored so a crafted
// fragment cannot inject unexpected behavior.

export const SHARE_FIELDS = Object.freeze([
  'hourlyWage', 'burdenRate', 'roundTripMinutes', 'setupMinutes', 'waterCost',
  'equipmentWear', 'otherCost', 'overheadRate', 'targetMargin', 'minimumJob',
  'packageVisits', 'packageDiscount', 'proposedPrice',
]);

// `name` travels as the surface preset's own label — `addSurfaceRow` matches
// it back to a preset index, or to "Other surface" when nothing matches — so
// a surface priced with a preset the sender edited (a custom production rate
// or chemical cost) restores as that preset, not as whichever preset happens
// to sit first in the list.
const SURFACE_KEYS = Object.freeze(['name', 'squareFeet', 'productionRate', 'chemicalCost']);

function pick(object, keys) {
  const out = {};
  for (const key of keys) {
    if (object[key] !== undefined) out[key] = object[key];
  }
  return out;
}

export function encodeShare(input) {
  const payload = pick(input || {}, SHARE_FIELDS);
  if (Array.isArray(input?.surfaces)) {
    payload.surfaces = input.surfaces.map(row => pick(row || {}, SURFACE_KEYS));
  }
  return encodeURIComponent(JSON.stringify(payload));
}

export function decodeShare(fragment) {
  if (!fragment) return null;
  const raw = String(fragment).replace(/^#/, '');
  if (!raw) return null;
  let parsed;
  try {
    parsed = JSON.parse(decodeURIComponent(raw));
  } catch {
    return null;
  }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return null;
  const payload = pick(parsed, SHARE_FIELDS);
  if (Array.isArray(parsed.surfaces)) {
    payload.surfaces = parsed.surfaces
      .map(row => pick(row || {}, SURFACE_KEYS))
      .filter(row => Object.keys(row).length > 0);
  }
  if (Object.keys(payload).length === 0) return null;
  return payload;
}

usage.mjs.text:
// Records an anonymous, aggregate-only local usage count: the event name and
// the current day, kept in the visitor's own browser. It never stores the
// address, the square footage, the wage, the price, or any other bid input,
// and it never leaves the device — a contractor's pricing is exactly the sort
// of thing that must not be transmitted anywhere.
function honorsBrowserSignal() {
  try {
    return globalThis.navigator?.doNotTrack === '1' || globalThis.navigator?.globalPrivacyControl === true;
  } catch {
    return false;
  }
}

export function recordUsage(storage = globalThis.localStorage, optedOut = false, event = 'bid_calculated') {
  if (optedOut || !storage || readOptOut(storage) || honorsBrowserSignal()) return;
  const today = new Date().toISOString().slice(0, 10);
  const current = JSON.parse(storage.getItem('pressure-washing-bid-usage') || '{}');
  current[event] = (current[event] || 0) + 1;
  current.last_day = today;
  storage.setItem('pressure-washing-bid-usage', JSON.stringify(current));
}

// The opt-out choice is kept in its own key, not in the counters:
// opting out *removes* the counters, so a flag stored inside them would
// be deleted by the very act it records. `recordUsage` above consults it
// directly as well as taking the caller's argument -- a stored preference
// that only one line of page wiring reads is one line away from being
// forgotten, which is the defect this change exists to fix.
export function readOptOut(storage = globalThis.localStorage) {
  try {
    return storage?.getItem('pressure-washing-bid-usage-opt-out') === '1';
  } catch {
    // A blocked or full store must never be read as consent.
    return false;
  }
}

export function writeOptOut(storage = globalThis.localStorage, optedOut = false) {
  if (!storage) return;
  // Independent writes, counters first: sharing one try means a setItem
  // that throws on a full quota skips the delete entirely, and the
  // visitor gets neither half of what the control promised.
  if (optedOut) {
    try { storage.removeItem('pressure-washing-bid-usage'); } catch { /* storage is optional */ }
    try { storage.setItem('pressure-washing-bid-usage-opt-out', '1'); } catch { /* storage is optional */ }
  } else {
    try { storage.removeItem('pressure-washing-bid-usage-opt-out'); } catch { /* storage is optional */ }
  }
}
